list_tax_rules.code:
use WebCommander\Sdk\Resources\TaxRules\TaxRules;

$response = TaxRules::listTaxRules($client, ['limit' => 20]);

foreach ($response->map['tax_rules'] as $rule) {
    echo $rule['id'], ' ', $rule['name'], ', ', count($rule['zones']), ' zones', PHP_EOL;
}
echo $response->map['pagination']['total'], ' tax rules in total', PHP_EOL;

create_tax_rule.code:
use WebCommander\Sdk\Resources\TaxRules\TaxRules;

$response = TaxRules::createTaxRule($client, [
    'tax_rule' => ['name' => 'Reduced rate', 'description' => 'Rule for reduced-rate goods'],
]);

echo $response->map['tax_rule']['id'], PHP_EOL;

get_tax_rule.code:
use WebCommander\Sdk\Resources\TaxRules\TaxRules;

$response = TaxRules::getTaxRule($client, 7);

$rule = $response->map['tax_rule'];
echo $rule['name'], ': ', $rule['description'], PHP_EOL;
foreach ($rule['zones'] as $zone) {
    echo 'zone ', $zone['id'], ' ', $zone['name'], PHP_EOL;
}

